UPDATE evaluation_criteria SET name = 'El prestador de servicios de salud cuenta con el registro de la relación de los equipos biomédicos requeridos para la prestación de servicios de salud, este registro cuenta como mínimo con la siguiente información: 1.1. Nombre del equipo biomédicos. 1.2. Marca. 1.3. Modelo. 1.4. Serie. 1.5. Registro sanitario para dispositivos médicos o permiso de comercialización para equipos biomédicos de tecnología controlada, cuando lo requiera. 1.6. Clasificación por riesgo, cuando el equipo lo requiera.' WHERE code = 'TSDOT-001';
UPDATE evaluation_criteria SET name = 'El prestador de servicios de salud garantiza las condiciones técnicas de calidad de los equipos biomédicos, para lo cual cuenta con: 2.1. Programa de mantenimiento preventivo de los equipos biomédicos, que incluya el cumplimiento de las recomendaciones establecidas por el fabricante o de acuerdo con el protocolo de mantenimiento que tenga definido el prestador, éste último cuando no esté definido por el fabricante. 2.2. Hoja(s) de vida del(los) equipo(s) biomédicos(s), con los registros de los mantenimientos preventivos y correctivos, según corresponda. de Prestadores y Habilitación de Servicios de Salud”' WHERE code = 'TSDOT-002';
UPDATE evaluation_criteria SET name = 'El prestador de servicios de salud cuenta con un programa de capacitación en el uso de dispositivos médicos cuando éstos lo requieran, el cual puede ser desarrollado por el fabricante, importador o por el mismo prestador.' WHERE code = 'TSDOT-003';
UPDATE evaluation_criteria SET name = 'La dotación de los servicios de salud está en concordancia con lo definido por el prestador en el estándar de procesos prioritarios.' WHERE code = 'TSDOT-004';
